let
  root = /home/dylan/src/aos/.worktrees/codex/bazel-integration-722;
  pkgs = (import root {}).pkgs;
  baseline = features: suffix: let
    original = pkgs.callPackage (root + "/pkgs/tools/aos-hub-worker-dist.nix") {cargoFeatures = features;};
    command = ''-j"$NIX_BUILD_CORES"'';
    capture = ''-j"$NIX_BUILD_CORES" --message-format=json > "$out/cargo-messages.jsonl"'';
  in original.overrideAttrs (old: {
    pname = "aos-bazel-hub-worker-wasm-" + suffix + "cargo-baseline";
    phases = map (phase:
      if phase.name != "build-wasm" then phase else
      assert builtins.length (pkgs.lib.splitString command phase.script) == 2;
      assert !(pkgs.lib.hasInfix "/dev/shm" phase.script);
      phase // {script = ''mkdir -p "$out"
'' + builtins.replaceStrings [command] [capture] phase.script;}
    ) old.phases;
  });
in {builds = [ (baseline "" "") (baseline "do-e2e" "do-e2e-") (baseline "query-timing do-e2e" "all-features-") ];}
